public record VoxelColumnData(SectionData[] sections, long columnTimestamp, boolean replaceMissingSections, int[] replacementSectionYs, boolean completesRequest) {
    private final int[] replacementSectionYs;

    public VoxelColumnData(SectionData[] sections, long columnTimestamp) {
        this(sections, columnTimestamp, false);
    }

    public VoxelColumnData(SectionData[] sections, long columnTimestamp, boolean replaceMissingSections) {
        this(sections, columnTimestamp, replaceMissingSections, new int[0]);
    }

    public VoxelColumnData(SectionData[] sections, long columnTimestamp, boolean replaceMissingSections, int[] replacementSectionYs) {
        this(sections, columnTimestamp, replaceMissingSections, replacementSectionYs, true);
    }

    public VoxelColumnData {
        if (sections == null) {
            sections = new SectionData[]{};
        }
        replacementSectionYs = replacementSectionYs == null ? new int[]{} : Arrays.copyOf(replacementSectionYs, replacementSectionYs.length);
    }

    public int[] replacementSectionYs() {
        return Arrays.copyOf(this.replacementSectionYs, this.replacementSectionYs.length);
    }

    public record SectionData(int sectionY, LevelChunkSection section, DataLayer blockLight, DataLayer skyLight) {
    }
}

