public final class VSSClientConfigScreens {
    private VSSClientConfigScreens() {
    }

    public static void register() {
        ModLoadingContext.get().registerExtensionPoint(ConfigScreenHandler.ConfigScreenFactory.class, () -> new ConfigScreenHandler.ConfigScreenFactory(VSSClientConfigScreens::createConfigScreen));
    }

    private static Screen createConfigScreen(Minecraft client, Screen parent) {
        Screen sodiumScreen = VSSVoxyOptionsIntegration.createSodiumConfigScreen(parent);
        if (sodiumScreen != null) {
            return sodiumScreen;
        }
        return new VSSServerConfigScreen(parent, VSSServerConfig.CONFIG);
    }
}

