        candidates.add(region);
    }
    int budget = 8 - inFlight;
    if (budget <= 0 || candidates.isEmpty()) {
        return;
    }
    candidates.sort((a, b) -> Integer.compare(b.tiles(), a.tiles()));
    List chosen = candidates.subList(0, Math.min(budget, candidates.size()));
