        return VSSServerNetworking.isColumnStillRelevant(player, payload.dimension(), payload.chunkX(), payload.chunkZ());
    }

    public static boolean isColumnStillRelevant(ServerPlayer player, ResourceKey<Level> dimension, int cx, int cz) {
        if (VSSServerNetworking.isServerStopping() || player == null || !VSSServerConfig.CONFIG.enabled) {
            return false;
        }
        if (!player.m_284548_().m_46472_().equals(dimension)) {
            return false;
        }
        int playerCx = player.m_146903_() >> 4;
        int playerCz = player.m_146907_() >> 4;
        int maxDistance = VSSServerConfig.CONFIG.effectiveColumnSyncDistanceChunks() + 32;
        return PositionUtil.chebyshevDistance(cx, cz, playerCx, playerCz) <= maxDistance;
    }

    private static void sendBackpressured(ServerPlayer player, int requestId) {
        VSSServerNetworking.sendResponse(player, requestId, (byte)3);
    }
